+  );
+}
+
+function AnalyticsScreen({
+  root,
+  path,
+  block,
+  runBlock,
+  run,
+}: {
+  root: WorkflowGraph;
+  path: string[];
+  block: WorkflowBlock;
+  runBlock: WorkflowBlock;
+  run: WorkflowRun | null;
+}) {
