+  return [...groups.entries()]
+    .map(([key, list]) => ({
+      key,
+      label: key === UNKNOWN_KEY ? "Unknown" : labelOf(key),
+      count: list.length,
+      share: list.length / total,
+      people: peopleCount(list),
+    }))
