+    const denominators = buckets.map(() => [] as AnalyticsRow[]);
+    for (const r of rows) {
+      if (r.time === null || !spec.includes(r)) continue;
+      const i = index.get(bucketStart(r.time, granularity));
+      if (i !== undefined) denominators[i]!.push(r);
+    }
