+/** What a phrase query found. */
+export interface PhraseStats {
+  query: PhraseQuery;
+  matches: AnalyticsRow[];
+  count: number;
+  share: number; // of the rows searched
+  people: number;
+  peopleShare: number; // of the people among the rows searched
