+
+/** A group of rows to compare (an input, a source, a country, a category value). */
+export interface Segment {
+  key: string;
+  label: string;
+  colorIndex: number;
+  rows: AnalyticsRow[];
+}
+
+export type CompareBy = "input" | "source" | "country" | `category:${string}`;
