+      key: String(i.index),
+      label: i.label,
+      colorIndex: i.index,
+      rows: rows.filter((r) => r.input === i.index),
+    }));
+  }
+  const keyOf: KeyOf =
+    by === "source"
+      ? (r) => r.sourceId
+      : by === "country"
+        ? (r) => r.country
+        : (r) => r.categories[by.slice("category:".length)] ?? null;
