+  const slots = colorSlots(all);
+  const titles = new Map(dataset.rows.map((r) => [r.sourceId, r.sourceTitle]));
+  return all.map((c) => ({
+    key: c.key,
+    label:
+      by === "source"
+        ? (titles.get(c.key) ?? c.key)
