+
+export interface FeatureComparison {
+  feature: Feature;
+  cells: {
+    segment: string;
+    count: number;
+    share: number;
+    /** Against all other segments together. */
+    vsRest: ReturnType<typeof compareShares>;
+  }[];
+  /** Largest minus smallest share among segments with rows. */
+  spread: number;
