+/** "2024-03-15" for a timestamp, in UTC. */
+export function formatDay(t: number): string {
+  const d = new Date(t);
+  const year = String(d.getUTCFullYear()).padStart(4, "0");
+  return `${year}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
+}

