+    if (values instanceof Float32Array) view.setFloat32(i * 4, values[i]!, true);
+    else view.setUint32(i * 4, values[i]!, true);
+  }
+  let text = "";
+  for (let i = 0; i < bytes.length; i += 16384)
+    text += String.fromCharCode(...bytes.subarray(i, i + 16384));
+  return btoa(text);
