+    (config.dimensions.width !== undefined &&
+      Math.abs(config.dimensions.width - size.z * scale) > 0.0005) ||
+    (config.dimensions.height !== undefined &&
+      Math.abs(config.dimensions.height - size.y * scale) > 0.0005)
