+          {state.status === "loading" ? "Loading the exact originating workflow…" : state.message}
+        </p>
+        {state.status === "error" && (
+          <Button className="mt-3" onClick={() => setAttempt((n) => n + 1)}>
+            Retry workflow origin
+          </Button>
