+    const configuration = {
+      ...rest,
+      fields: [
+        ...new Set(
+          rawFields
+            .split(",")
+            .map((v) => v.trim())
+            .filter(Boolean),
+        ),
+      ],
+    };
+    const hashConfiguration = {
