+      const byId = new Map(selected.data.decisions.map((decision) => [decision.id, decision]));
+      if (
+        byId.size !== current.length ||
+        selected.data.decisions.length !== current.length ||
+        current.some((entry) => !byId.has(entry.id))
+      )
