+
+  async restore(
+    workflowId: string,
+    blockId: string,
+    report: FilterReport,
+    review: FilterReview,
+    actor: Actor,
+  ): Promise<FilterReviewState> {
+    WorkflowId.parse(workflowId);
+    BlockId.parse(blockId);
