+          `Block run for "${blockId}" has status "${targetBlockRun.status}", expected "succeeded"`,
+        );
+      }
+      if (!targetBlockRun.filterReport) {
+        throw new FilterOverrideStateError(
+          `Authoritative filter report is missing from block "${blockId}"`,
+        );
+      }
