+    return () => { element?.close(); if (trigger instanceof HTMLElement && trigger.isConnected) trigger.focus(); };
+  }, [open]);
+
+  const load = async (id: string) => {
+    if (await workflowStore.getState().load(id, replaceConfirmed)) setOpen(false);
+  };
