+      <p className="text-xs text-ink">{status ? BLOCK_STATUS_LABELS[status.status] : "Not executed"} / {run.scope.market} / {new Date(run.startedAt).toLocaleString()}</p>
+      <p className="break-all font-mono text-[10px] text-muted">{run.id}</p>
+      <p className="text-xs text-muted">Read-only frozen snapshot. {blockDraftChanged(block, saved) ? "This draft has changed; the output below still belongs to the saved block and its original ports." : "Edits apply only to a later run."}</p>
+      {status?.error && <p role="alert" className="text-xs text-danger">{status.error}</p>}
