+  return (
+    <aside data-testid="workflow-problems" aria-label="Workflow problems" className="fixed top-36 bottom-24 left-4 z-30 flex w-80 max-w-[calc(100vw-2rem)] flex-col rounded-xl border border-line bg-panel shadow-xl">
