+              const graph = problem.path.reduce((current, id) => current.blocks.find((block) => block.id === id)!.inner!, root);
+              const blockId = problem.blockId ?? graph.edges.find((edge) => edge.id === problem.edgeId)?.target;
+              if (blockId) dataflowStore.getState().revealBlock(problem.path, blockId);
+              else dataflowStore.getState().goTo(0);
+              onClose();
+            }}>
+              <span className="block font-medium">{problem.path.length ? "Inner workplace" : "Main workplace"}</span>
+              <span>{problem.message}</span>
+            </button>
+          ))}
+        </div>
+      </div>
+    </aside>
+  );
+}

