+
+  const info = await invoke<{ dataDir: string }>("app.info");
+  assert(resolve(info.dataDir) === resolve(data), "Probe refused non-isolated data directory");
+  await invoke("settings.save", { ...DEFAULT_SETTINGS, llm: { ...DEFAULT_SETTINGS.llm, provider: "mock" } });
+  await js("window.confirm = () => true");
+  await wait(() => js("Boolean(document.querySelector('[data-testid=workflow-new]'))"), "Workflow toolbar did not render");
