+  await click('[data-testid="palette-item-raw"]');
+  await click('[data-testid="palette-item-hil"]');
+  assert(await count() === 2, "Palette adds failed");
+  await click('[data-testid="editor-undo"]');
+  assert(await count() === 1, "Undo did not remove last addition");
+  await click('[data-testid="editor-redo"]');
+  assert(await count() === 2, "Redo did not restore addition");
+  await click('[data-testid="editor-duplicate"]');
+  assert(await count() === 3, "Duplicate did not add a new block");
+  await click('[data-testid="editor-copy"]');
+  await click('[data-testid="editor-paste"]');
+  assert(await count() === 4, "Paste did not add copied block");
+  await shortcut("Z");
+  assert(await count() === 3, "Native keyboard undo did not apply");
+  await shortcut("Z", true);
+  assert(await count() === 4, "Native keyboard redo did not apply");
+  await click('[data-testid="editor-problems"]');
+  assert((await text('[data-testid="workflow-problems"]')).includes("uploaded file"), "Problems did not identify missing source");
+  await screenshot("editor-history-problems");
+  await js("document.querySelector('[data-testid=workflow-problems] button').click()");
+  await click('[data-testid="editor-tidy"]');
+  await screenshot("editor-tidied");
+  await setName("Synthetic autosave probe");
+  await wait(async () => (await text('[data-testid="workflow-save-status"]')).startsWith("Saved"), "Autosave did not settle");
+  const saved = (await invoke<Workflow[]>("workflows.list")).find((flow) => flow.name === "Synthetic autosave probe")!;
+  assert(saved?.blocks.length === 4, "Autosave stored wrong graph or name");
+  assert((await invoke<WorkflowRun[]>("runs.list", saved.id)).length === 0, "Save-only unexpectedly executed a workflow");
+  wc.reload();
+  await wait(() => js("document.querySelector('[data-testid=workflow-name]')?.value === 'Synthetic autosave probe'"), "Last workflow was not restored after renderer reload");
+  assert(await count() === 4, "Reload did not restore graph");
+
+  const raw = createBlock("raw", { id: "probe-raw", position: { x: 0, y: 0 } });
+  raw.params = { ...raw.params, source: "database", connection: databasePath, query: "SELECT * FROM feedback", dataset: "customer_feedback" };
+  const hil = createBlock("hil", { id: "probe-hil", position: { x: 340, y: 0 } });
+  const graph = connect({ blocks: [raw, hil], edges: [] }, { source: raw.id, sourcePort: "out", target: hil.id, targetPort: "in" });
+  const executable = await invoke<Workflow>("workflows.save", { ...graph, name: "Synthetic saved-run probe", scope: { ...DEFAULT_SETTINGS.defaultScope, market: "US" } });
+  await click('[data-testid="workflow-open"]');
